#include "maze.h"
#include "drawing.h"
#include <stdlib.h>

// Fisher-Yates shuffle algorithm used to randomize the order of items in an array
// This function is generated by OpenAI GPT-6.1-Sol
void shuffleDirections(Vec2 directions[], int size) {
    for (int i = size - 1; i > 0; i--) {
        int chosen = rand() % (i + 1);

        Vec2 temporary = directions[i];
        directions[i] = directions[chosen];
        directions[chosen] = temporary;
    }
}

// Randomized DFS creates passages in the grid by replacing WALL_CELLs with EMPTY_CELLs
void createPassages(int cellGrid[MAX_GRID_WIDTH][MAX_GRID_HEIGHT], Vec2 currentPosition,
                    int width, int height, int generationDelay) {
    // Shuffle a local copy of the directions
    Vec2 directions[DIRECTION_COUNT] = {DIRECTION_OFFSETS[UP], DIRECTION_OFFSETS[RIGHT], DIRECTION_OFFSETS[DOWN], DIRECTION_OFFSETS[LEFT]};
    shuffleDirections(directions, DIRECTION_COUNT);

    for (int i = 0; i < DIRECTION_COUNT; i++) {
        Vec2 nextPosition = {currentPosition.x + directions[i].x * 2, currentPosition.y + directions[i].y * 2};
        Vec2 inbetweenPosition = {currentPosition.x + directions[i].x, currentPosition.y + directions[i].y};

        if (nextPosition.x <= 0 || nextPosition.x >= width - 1 || nextPosition.y <= 0 || nextPosition.y >= height - 1) {
            continue;
        }

        if (cellGrid[nextPosition.x][nextPosition.y] != WALL_CELL) {
            continue;
        }

        cellGrid[inbetweenPosition.x][inbetweenPosition.y] = EMPTY_CELL;
        cellGrid[nextPosition.x][nextPosition.y] = EMPTY_CELL;
        drawCell(cellGrid[inbetweenPosition.x][inbetweenPosition.y], inbetweenPosition);
        drawCell(cellGrid[nextPosition.x][nextPosition.y], nextPosition); // update the drawn cells to show the new passage being created
        sleep(generationDelay);
        createPassages(cellGrid, nextPosition, width, height, generationDelay);
    }
}

void createMaze(int cellGrid[MAX_GRID_WIDTH][MAX_GRID_HEIGHT], int width, int height,
                int generationDelay) {
    for (int x = 0; x < width; x++) {
        for (int y = 0; y < height; y++) {
            cellGrid[x][y] = WALL_CELL;
        }
    }

    drawMaze(cellGrid, width, height);

    Vec2 entrancePosition = {0, 1};
    Vec2 startPosition = {1, 1};
    cellGrid[entrancePosition.x][entrancePosition.y] = EMPTY_CELL; // Create an entrance to the maze
    cellGrid[startPosition.x][startPosition.y] = EMPTY_CELL; // Create a starting position for the maze generation algorithm
    drawCell(cellGrid[entrancePosition.x][entrancePosition.y], entrancePosition);
    drawCell(cellGrid[startPosition.x][startPosition.y], startPosition);
    sleep(generationDelay);

    createPassages(cellGrid, startPosition, width, height, generationDelay);

    Vec2 exitPosition = {width - 1, height - 2};
    if (exitPosition.y % 2 == 0) {
        // Passages occupy odd rows, so move the exit up for even-height grids.
        exitPosition.y--;
    }
    // Even-width grids need one extra passage to reach the right border.
    Vec2 exitApproach = {exitPosition.x - 1, exitPosition.y};
    if (cellGrid[exitApproach.x][exitApproach.y] == WALL_CELL) {
        cellGrid[exitApproach.x][exitApproach.y] = EMPTY_CELL;
        drawCell(EMPTY_CELL, exitApproach);
    }
    cellGrid[exitPosition.x][exitPosition.y] = EXIT_CELL;
    drawCell(cellGrid[exitPosition.x][exitPosition.y], exitPosition);
}

int isInsideGrid(Vec2 position, int width, int height) {
    return position.x >= 0 && position.x < width &&
           position.y >= 0 && position.y < height;
}
